import ast
from pathlib import Path
for path in sorted(Path('kvstore').glob('*.py')):
    tree=ast.parse(path.read_text())
    for node in ast.walk(tree):
        if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef)):
            length=(node.end_lineno or node.lineno)-node.lineno+1
            if length>60: print(path,node.name,length)
            public=not node.name.startswith('_')
            args=node.args.posonlyargs+node.args.args+node.args.kwonlyargs
            missing=[a.arg for a in args if a.arg not in ('self','cls') and a.annotation is None]
            if public and (missing or node.returns is None): print('ANNOTATION',path,node.name,missing,node.returns is None)
